<include file="Public:header"/>	<div class="mainbox">		<table class="search_table" width="100%">			<tr>				<td style="width:60%;">					<if condition = "$_GET['type'] eq 'withdraw'">						总提现列表					<elseif condition="$_GET['type'] eq 'system_take'"/>						总抽成列表					<else/>						平台余额列表					</if>				</td>			</tr>		</table>					<div class="table-list">				<table width="100%" cellspacing="0">					<colgroup><col> <col><col width="240" align="center"> </colgroup>					<thead>						<tr>							<th>金额</th>							<if condition="$_GET['type'] eq 'system_take'">								<th>抽成</th>							</if>							<th>描述</th>							<th>时间</th>						</tr>					</thead>					<tbody>						<if condition="is_array($list)">							<volist name="list" id="vo">								<tr>									<td>{pigcms{$vo.money}</td>									<if condition="$_GET['type'] eq 'system_take'">										<td>{pigcms{$vo.system_take}</td>									</if>									<td>{pigcms{$vo.desc}</td>									<td>{pigcms{$vo.use_time|date='Y-m-d H:i:s',###}</td>								</tr>							</volist>							<tr><td class="textcenter pagebar" colspan="5">{pigcms{$pagebar}</td></tr>						<else/>							<tr><td class="textcenter red" colspan="5">列表为空！</td></tr>						</if>					</tbody>				</table>			</div>	</div><include file="Public:footer"/>